import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

// Generated by assay from a real run of smith.
//   finding j-5-announce-grammar — clause press-2485e417 broken at event e55
//   smith scaffold emitted an ungrammatical announce line ('to grades a real run') because the template lowercases a third-person summary and splices it after 'to'
//
// This test was RED when it was generated: the string below was present, which
// is the defect. It is not a style preference and deleting it is not a fix.
const HERE = dirname(fileURLToPath(import.meta.url));
const SKILL = join(HERE, '..', '..', '..');

test('j-5-announce-grammar: smith no longer skill to ${spec.summary[0].toLowerCase()}"…', () => {
  const body = readFileSync(join(SKILL, "scripts/lib/templates.mjs"), 'utf8');
  assert.ok(
    !body.includes("skill to ${spec.summary[0].toLowerCase()}"),
    "scripts/lib/templates.mjs still contains the text this finding is about — smith scaffold emitted an ungrammatical announce line ('to grades a real run') because the template lowercases a third-person summary and splices it after 'to'",
  );
});
